// Hand-written. Not generated by Speakeasy.
package customtypes

import (
	"context"
	"github.com/hashicorp/terraform-plugin-framework/attr/xattr"
	"github.com/hashicorp/terraform-plugin-framework/diag"
	"github.com/hashicorp/terraform-plugin-framework/path"
	"strings"
	"testing"
)

func TestJWKSSemanticEquals(t *testing.T) {
	for name, tc := range map[string]struct {
		a, b string
		want bool
	}{
		// The real case: Authlete strips whitespace and reorders members.
		"formatting and key order differ": {
			a:    "{\n  \"keys\": [\n    {\n      \"kty\": \"RSA\",\n      \"kid\": \"k1\"\n    }\n  ]\n}",
			b:    `{"keys":[{"kid":"k1","kty":"RSA"}]}`,
			want: true,
		},
		"identical":            {a: `{"keys":[]}`, b: `{"keys":[]}`, want: true},
		"different key id":     {a: `{"keys":[{"kid":"k1"}]}`, b: `{"keys":[{"kid":"k2"}]}`, want: false},
		"extra key in set":     {a: `{"keys":[{"kid":"k1"}]}`, b: `{"keys":[{"kid":"k1"},{"kid":"k2"}]}`, want: false},
		"key order in array":   {a: `{"keys":[{"kid":"a"},{"kid":"b"}]}`, b: `{"keys":[{"kid":"b"},{"kid":"a"}]}`, want: false},
		"both unparseable":     {a: `not json`, b: `not json`, want: true},
		"one unparseable":      {a: `{"keys":[]}`, b: `not json`, want: false},
		"empty against object": {a: ``, b: `{"keys":[]}`, want: false},
	} {
		t.Run(name, func(t *testing.T) {
			got, diags := NewJWKSValue(tc.a).StringSemanticEquals(context.Background(), NewJWKSValue(tc.b))
			if diags.HasError() {
				t.Fatalf("unexpected diagnostics: %v", diags)
			}
			if got != tc.want {
				t.Errorf("semantic equality = %v, want %v", got, tc.want)
			}
		})
	}
}

func validateJWKS(t *testing.T, doc string) diag.Diagnostics {
	t.Helper()
	var resp xattr.ValidateAttributeResponse
	NewJWKSValue(doc).ValidateAttribute(context.Background(),
		xattr.ValidateAttributeRequest{Path: path.Root("jwks")}, &resp)
	return resp.Diagnostics
}

// TestDuplicateKidIsRefused covers what jwk_from_pem cannot see: that function
// is handed one key and knows nothing about the others in the set.
func TestDuplicateKidIsRefused(t *testing.T) {
	d := validateJWKS(t, `{"keys":[
		{"kty":"RSA","kid":"dup","alg":"RS256","use":"sig"},
		{"kty":"EC","kid":"dup","alg":"ES256","use":"sig"}
	]}`)
	if !d.HasError() {
		t.Fatal("accepted two keys sharing a kid; which one Authlete picks would be undefined")
	}
	if !strings.Contains(d.Errors()[0].Summary(), "dup") {
		t.Errorf("error does not name the kid: %s", d.Errors()[0].Summary())
	}
}

func TestKeyWithoutKidIsRefused(t *testing.T) {
	for _, doc := range []string{
		`{"keys":[{"kty":"RSA","alg":"RS256","use":"sig"}]}`,
		`{"keys":[{"kty":"RSA","kid":"","alg":"RS256","use":"sig"}]}`,
		`{"keys":[{"kty":"RSA","kid":"   ","alg":"RS256","use":"sig"}]}`,
	} {
		if d := validateJWKS(t, doc); !d.HasError() {
			t.Errorf("accepted a key with no usable kid: %s", doc)
		}
	}
}

func TestDistinctKidsAreAccepted(t *testing.T) {
	d := validateJWKS(t, `{"keys":[
		{"kty":"RSA","kid":"rsa1","alg":"RS256","use":"sig"},
		{"kty":"EC","kid":"ec1","alg":"ES256","use":"sig"}
	]}`)
	if d.HasError() {
		t.Errorf("refused a valid set: %v", d.Errors())
	}
}

// TestUnparseableIsLeftAlone keeps this check from duplicating the server's
// own error, and from rejecting a shape it does not model.
func TestUnparseableIsLeftAlone(t *testing.T) {
	for _, doc := range []string{"not json", `{"keys":"not a list"}`, `{}`} {
		if d := validateJWKS(t, doc); d.HasError() {
			t.Errorf("reported an error for %q, which this check should leave to the server: %v", doc, d.Errors())
		}
	}
}

// The set-level half of the algorithm confusion check. jwk_from_pem already
// refuses these, but a JWK Set written by hand never goes through it.
func TestImpossibleAlgIsRefused(t *testing.T) {
	for name, doc := range map[string]string{
		"HMAC alg on an RSA key": `{"keys":[{"kty":"RSA","kid":"k","alg":"HS256","use":"sig"}]}`,
		"HMAC alg on an EC key":  `{"keys":[{"kty":"EC","kid":"k","crv":"P-256","alg":"HS256","use":"sig"}]}`,
		"alg none":               `{"keys":[{"kty":"RSA","kid":"k","alg":"none","use":"sig"}]}`,
		"RSA alg on an EC key":   `{"keys":[{"kty":"EC","kid":"k","crv":"P-256","alg":"RS256","use":"sig"}]}`,
		"EC alg on an RSA key":   `{"keys":[{"kty":"RSA","kid":"k","alg":"ES256","use":"sig"}]}`,
		"EdDSA on an RSA key":    `{"keys":[{"kty":"RSA","kid":"k","alg":"EdDSA","use":"sig"}]}`,
		"ES256 on P-384":         `{"keys":[{"kty":"EC","kid":"k","crv":"P-384","alg":"ES256","use":"sig"}]}`,
		"ES512 on P-256":         `{"keys":[{"kty":"EC","kid":"k","crv":"P-256","alg":"ES512","use":"sig"}]}`,
	} {
		t.Run(name, func(t *testing.T) {
			if d := validateJWKS(t, doc); !d.HasError() {
				t.Errorf("accepted %s: %s", name, doc)
			}
		})
	}
}

// Only impossible combinations are refused. An algorithm this provider has not
// been taught is not an error: the registry is extensible, and rejecting one
// would break a working configuration the day Authlete supports it.
func TestUnrecognisedAlgIsAccepted(t *testing.T) {
	for name, doc := range map[string]string{
		"no alg at all":                  `{"keys":[{"kty":"RSA","kid":"k","use":"sig"}]}`,
		"alg this package does not know": `{"keys":[{"kty":"RSA","kid":"k","alg":"SOMETHING-NEW","use":"sig"}]}`,
		"no kty to check against":        `{"keys":[{"kid":"k","alg":"RS256","use":"sig"}]}`,
		"EC signing alg with no crv":     `{"keys":[{"kty":"EC","kid":"k","alg":"ES256","use":"sig"}]}`,
		"HMAC on a symmetric key":        `{"keys":[{"kty":"oct","kid":"k","alg":"HS256","use":"sig"}]}`,
		"RSA-OAEP on an RSA key":         `{"keys":[{"kty":"RSA","kid":"k","alg":"RSA-OAEP-256","use":"enc"}]}`,
		"ECDH-ES on an EC key":           `{"keys":[{"kty":"EC","kid":"k","crv":"P-521","alg":"ECDH-ES","use":"enc"}]}`,
		"EdDSA on an OKP key":            `{"keys":[{"kty":"OKP","kid":"k","crv":"Ed25519","alg":"EdDSA","use":"sig"}]}`,
	} {
		t.Run(name, func(t *testing.T) {
			if d := validateJWKS(t, doc); d.HasError() {
				t.Errorf("refused %s: %v", name, d.Errors())
			}
		})
	}
}
